94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    /** Matches a syntactically valid email address: a local part and domain (with at least one dot)
103	     *  separated by '@', none of which contain whitespace or a second '@'. */
104	    private static final java.util.regex.Pattern EMAIL_PATTERN =
105	        java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
106	
107	    /**
108	     * Normalize the optional email: absent stays absent; when present it must be syntactically
109	     * valid and is lower-cased. Returns {@code false} if present but invalid.
110	     */
111	    private boolean normalizeEmail(Owner owner) {
112	        String email = owner.getEmail();
113	        if (email == null || email.isEmpty()) {
114	            owner.setEmail(null);
115	            return true;
116	        }
117	        if (!EMAIL_PATTERN.matcher(email).matches()) {
118	            return false;
119	        }
120	        owner.setEmail(email.toLowerCase(java.util.Locale.ROOT));
121	        return true;
122	    }
123	
124	    /**
125	     * Normalize a telephone number to E.164 form: strip spaces, dashes and brackets; keep a leading
126	     * '+' and country code when present, otherwise assume country code '+61' and drop a single leading
127	     * '0' from the national digits. The result must have 8 to 15 digits after the '+'.
128	     *
129	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when the input cannot form
130	     *         a valid E.164 number.
131	     */
132	    private static String toE164(String raw) {
133	        if (raw == null) {
134	            return null;
135	        }
136	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
137	        String digits;
138	        if (cleaned.startsWith("+")) {
139	            digits = cleaned.substring(1);
140	        } else {
141	            if (cleaned.startsWith("0")) {
142	                cleaned = cleaned.substring(1);
143	            }
144	            digits = "61" + cleaned;
145	        }
146	        if (!digits.matches("\\d{8,15}")) {
147	            return null;
148	        }
149	        return "+" + digits;
150	    }
151	
152	    /**
153	     * Validate the national-number length of a canonical E.164 string against its country code:
154	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Numbers carrying any
155	     * other country code are not length-checked here and are accepted. Expects the '+'-prefixed digit
156	     * string produced by {@link #toE164}.
157	     *
158	     * @return {@code true} when the national-number length is correct for the country code.
159	     */
160	    private static boolean hasValidNationalLength(String e164) {
161	        String digits = e164.substring(1);
162	        if (digits.startsWith("61")) {
163	            return digits.length() - 2 == 9;
164	        }
165	        if (digits.startsWith("1")) {
166	            return digits.length() - 1 == 10;
167	        }
168	        return true;
169	    }
170	
171	    /**
172	     * Build the customer code {@code <REGION>-<HASH8>}: REGION is the region code derived from the
173	     * owner's postcode (NSW/VIC/QLD, or {@code UNKNOWN} when the postcode is absent or in no known
174	     * range) and HASH8 is the first 8 upper-case hex characters of SHA-256 over the concatenation of
175	     * the owner's normalized (E.164) telephone and last name (e.g. {@code NSW-3F9A0C17}). No sequence
176	     * numbers are used, so the code is a pure function of the owner's region-and-hash identity.
177	     */
178	    private String customerCodeFor(Owner owner) {
179	        String region = ownerMapper.regionFromPostcode(owner);
180	        if (region == null) {
181	            region = "UNKNOWN";
182	        }
183	        return region + "-" + hash8(owner.getTelephone(), owner.getLastName());
184	    }
185	
186	    /**
187	     * First 8 upper-case hex characters (the first 4 bytes) of SHA-256 over
188	     * {@code normalizedTelephone + lastName}, treating a {@code null} component as empty.
189	     */
190	    private static String hash8(String normalizedTelephone, String lastName) {
191	        String input = (normalizedTelephone == null ? "" : normalizedTelephone)
192	            + (lastName == null ? "" : lastName);
193	        try {
194	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
195	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
196	            StringBuilder sb = new StringBuilder(8);
197	            for (int i = 0; i < 4; i++) {
198	                sb.append(String.format("%02X", digest[i]));
199	            }
200	            return sb.toString();
201	        }
202	        catch (java.security.NoSuchAlgorithmException e) {
203	            throw new IllegalStateException(e);
204	        }
205	    }
206	
207	    /** Common street-type abbreviations expanded during address normalization. */
208	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
209	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
210	
211	    /**
212	     * Normalize an address: {@code null} becomes empty, surrounding whitespace is trimmed, internal
213	     * runs of whitespace are collapsed to a single space, the value is upper-cased and common
214	     * street-type abbreviations (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE) are expanded token by token.
215	     */
216	    private static String normalizeAddress(String value) {
217	        if (value == null) {
218	            return "";
219	        }
220	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
221	        if (collapsed.isEmpty()) {
222	            return "";
223	        }
224	        String[] tokens = collapsed.split(" ");
225	        StringBuilder sb = new StringBuilder(collapsed.length());
226	        for (int i = 0; i < tokens.length; i++) {
227	            if (i > 0) {
228	                sb.append(' ');
229	            }
230	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
231	        }
232	        return sb.toString();
233	    }
234	
235	    /**
236	     * Normalize a value for household-duplicate comparison: {@code null} becomes empty, surrounding
237	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space and the result
238	     * is lower-cased, so the comparison is case-insensitive with collapsed whitespace.
239	     */
240	    private static String normalizeForHousehold(String value) {
241	        if (value == null) {
242	            return "";
243	        }
244	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
245	    }
246	
247	    /**
248	     * Return the owners that already share this owner's household, i.e. resolve to the same
249	     * deterministic {@link #householdIdFor(Owner) householdId} (same normalized last name and
250	     * postcode).
251	     */
252	    private List<Owner> householdMembers(Owner owner) {
253	        String householdId = householdIdFor(owner);
254	        List<Owner> members = new java.util.ArrayList<>();
255	        for (Owner existing : this.clinicService.findAllOwners()) {
256	            if (householdId.equals(householdIdFor(existing))) {
257	                members.add(existing);
258	            }
259	        }
260	        return members;
261	    }
262	
263	    /**
264	     * Return {@code true} when another owner already shares this owner's household, i.e. resolves to
265	     * the same deterministic {@link #householdIdFor(Owner) householdId}.
266	     */
267	    private boolean sharesHouseholdWithExisting(Owner owner) {
268	        return !householdMembers(owner).isEmpty();
269	    }
270	
271	    /**
272	     * Count the existing owners that share this owner's first name and last name, compared
273	     * case-insensitively. Used to populate {@code namesakeCount} on create (before this owner is saved).
274	     */
275	    private int namesakeCount(Owner owner) {
276	        String firstName = owner.getFirstName();
277	        String lastName = owner.getLastName();
278	        int count = 0;
279	        for (Owner existing : this.clinicService.findAllOwners()) {
280	            if (firstName != null && lastName != null
281	                && firstName.equalsIgnoreCase(existing.getFirstName())
282	                && lastName.equalsIgnoreCase(existing.getLastName())) {
283	                count++;
284	            }
285	        }
286	        return count;
287	    }
288	
289	    /**
290	     * A stable, shared household identifier: the first 12 hex characters of SHA-256 over
291	     * {@code normalizedLastName + '|' + postcode} (an absent postcode contributes an empty string).
292	     * Because it is a pure function of the last name and postcode, every owner in the same household
293	     * deterministically resolves to the same value.
294	     */
295	    private static String householdIdFor(Owner owner) {
296	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
297	        String key = normalizeForHousehold(owner.getLastName()) + "|" + postcode;
298	        try {
299	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
300	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
301	            StringBuilder sb = new StringBuilder(12);
302	            for (int i = 0; i < 6; i++) {
303	                sb.append(String.format("%02X", digest[i]));
304	            }
305	            return sb.toString();
306	        }
307	        catch (java.security.NoSuchAlgorithmException e) {
308	            throw new IllegalStateException(e);
309	        }
310	    }
311	
312	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
313	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
314	        "NSW", new int[] {2000, 2099},
315	        "VIC", new int[] {3000, 3099},
316	        "QLD", new int[] {4000, 4099});
317	
318	    /**
319	     * Validate the optional postcode. Absent (null/empty) is valid — postcode is optional. When
320	     * present it must be exactly 4 digits; and when the owner's city maps to a known region (via the
321	     * mapper's fixed city-to-region table) it must fall inside that region's inclusive range
322	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
323	     * postcode.
324	     */
325	    private boolean isPostcodeValid(Owner owner) {
326	        String postcode = owner.getPostcode();
327	        if (postcode == null || postcode.isEmpty()) {
328	            return true;
329	        }
330	        if (!postcode.matches("\\d{4}")) {
331	            return false;
332	        }
333	        int[] range = REGION_POSTCODE_RANGES.get(ownerMapper.cityRegion(owner));
334	        if (range == null) {
335	            return true;
336	        }
337	        int value = Integer.parseInt(postcode);
338	        return value >= range[0] && value <= range[1];
339	    }
340	
341	    /**
342	     * Find an existing owner that makes this (already known to be non-hard-duplicate) owner a
343	     * "possible duplicate": one that shares the owner's last name (case-insensitive) and postcode
344	     * but carries a different (normalized) telephone. When several match, the one with the smallest
345	     * id is chosen so the result is deterministic. Returns {@code null} when the owner has no
346	     * postcode or no such existing owner exists.
347	     */
348	    private Owner possibleDuplicateOf(Owner owner) {
349	        String lastName = owner.getLastName();
350	        String postcode = owner.getPostcode();
351	        String telephone = owner.getTelephone();
352	        if (lastName == null || postcode == null || postcode.isEmpty()) {
353	            return null;
354	        }
355	        Owner match = null;
356	        for (Owner existing : this.clinicService.findAllOwners()) {
357	            if (lastName.equalsIgnoreCase(existing.getLastName())
358	                && postcode.equals(existing.getPostcode())
359	                && !java.util.Objects.equals(telephone, existing.getTelephone())) {
360	                if (match == null || (existing.getId() != null && match.getId() != null
361	                    && existing.getId() < match.getId())) {
362	                    match = existing;
363	                }
364	            }
365	        }
366	        return match;
367	    }
368	
369	    /** Maximum number of owners permitted in a single city. */
370	    private static final int CITY_CAPACITY = 50;
371	
372	    /** Maximum number of owners that may be created (by registrationDate) on a single day. */
373	    private static final int DAILY_CREATE_LIMIT = 100;
374	
375	    /** Number of owners already created on a day beyond which a bulk-signup warning is flagged. */
376	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
377	
378	    /**
379	     * Count the existing owners whose city matches this owner's city, compared case-insensitively.
380	     * Used to enforce the per-city capacity on create (before this owner is saved).
381	     */
382	    private int cityOwnerCount(Owner owner) {
383	        String city = owner.getCity();
384	        int count = 0;
385	        for (Owner existing : this.clinicService.findAllOwners()) {
386	            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
387	                count++;
388	            }
389	        }
390	        return count;
391	    }
392	
393	    /**
394	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
395	     * following Monday, any weekday is returned unchanged. Applied to the effective registration date
396	     * (supplied or defaulted) so that everything derived from it — the stored {@code registrationDate},
397	     * the membership number's year segment and the per-day create limit — uses the adjusted date.
398	     */
399	    private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
400	        switch (date.getDayOfWeek()) {
401	            case SATURDAY:
402	                return date.plusDays(2);
403	            case SUNDAY:
404	                return date.plusDays(1);
405	            default:
406	                return date;
407	        }
408	    }
409	
410	    /**
411	     * Count the existing owners whose registrationDate equals the given day. Used to enforce the
412	     * per-day create limit on create (before this owner is saved).
413	     */
414	    private int ownersRegisteredOn(java.time.LocalDate day) {
415	        int count = 0;
416	        for (Owner existing : this.clinicService.findAllOwners()) {
417	            if (day.equals(existing.getRegistrationDate())) {
418	                count++;
419	            }
420	        }
421	        return count;
422	    }
423	
424	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
425	    @Override
426	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
427	        HttpHeaders headers = new HttpHeaders();
428	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
429	        if (!isPostcodeValid(owner)) {
430	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
431	        }
432	        String telephone = toE164(owner.getTelephone());
433	        if (telephone == null || !hasValidNationalLength(telephone)) {
434	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
435	        }
436	        if (!normalizeEmail(owner)) {
437	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
438	        }
439	        String address = normalizeAddress(owner.getAddress());
440	        if (address.isEmpty()) {
441	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
442	        }
443	        owner.setAddress(address);
444	        owner.setTelephone(telephone);
445	        if (owner.getRegistrationDate() != null
446	            && owner.getRegistrationDate().isAfter(java.time.LocalDate.now())) {
447	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
448	        }
449	        java.time.LocalDate registrationDate = toBusinessDay(
450	            owner.getRegistrationDate() == null ? java.time.LocalDate.now() : owner.getRegistrationDate());
451	        int ownersRegisteredToday = ownersRegisteredOn(registrationDate);
452	        if (ownersRegisteredToday >= DAILY_CREATE_LIMIT) {
453	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
454	        }
455	        if (cityOwnerCount(owner) >= CITY_CAPACITY) {
456	            return new ResponseEntity<>(HttpStatus.CONFLICT);
457	        }
458	        // The householdId is deterministic (SHA-256 over normalized lastName + '|' + postcode), so
459	        // owners with the same last name and postcode automatically share it. The link is no longer
460	        // created by copying an existing owner's id around.
461	        owner.setHouseholdId(householdIdFor(owner));
462	        List<Owner> householdMembers = householdMembers(owner);
463	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
464	        boolean declaredHouseholdMember = sharesHousehold && !householdMembers.isEmpty();
465	
466	        // Hard duplicate: a new owner whose WHOLE identityKey (telephone|email|householdId) equals an
467	        // existing owner's is a byte-for-byte identity match and is always rejected.
468	        String identityKey = owner.getIdentityKey();
469	        for (Owner existing : this.clinicService.findAllOwners()) {
470	            if (identityKey.equals(existing.getIdentityKey())) {
471	                return new ResponseEntity<>(HttpStatus.CONFLICT);
472	            }
473	        }
474	        // Household duplicate: another owner already shares this (last name, postcode) household.
475	        // Rejected as a duplicate unless the caller sets 'sharesHousehold', which now only bypasses
476	        // this block (the shared householdId itself is already assigned deterministically above).
477	        if (!householdMembers.isEmpty() && !sharesHousehold) {
478	            return new ResponseEntity<>(HttpStatus.CONFLICT);
479	        }
480	        // A declared household member is not a suspected duplicate. Otherwise, flag an owner that
481	        // shares an existing owner's last name and postcode with a different telephone.
482	        if (declaredHouseholdMember) {
483	            owner.setPossibleDuplicate(false);
484	            owner.setPossibleDuplicateOf(null);
485	        }
486	        else {
487	            Owner duplicateOf = possibleDuplicateOf(owner);
488	            owner.setPossibleDuplicate(duplicateOf != null);
489	            owner.setPossibleDuplicateOf(duplicateOf == null ? null : duplicateOf.getId());
490	        }
491	        owner.setNamesakeCount(namesakeCount(owner));
492	        owner.setHouseholdSize(householdMembers.size() + 1);
493	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
494	        owner.setRegistrationDate(registrationDate);
495	        owner.setCustomerCode(customerCodeFor(owner));
496	        this.clinicService.saveOwner(owner);
497	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
498	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
499	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
500	        headers.setLocation(UriComponentsBuilder.newInstance()
501	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
502	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
503	    }
504	
505	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
506	    @Override
507	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
508	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
509	        if (currentOwner == null) {
510	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
511	        }
512	        currentOwner.setAddress(ownerFieldsDto.getAddress());
513	        currentOwner.setCity(ownerFieldsDto.getCity());
514	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
515	        currentOwner.setLastName(ownerFieldsDto.getLastName());
516	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
517	        currentOwner.setEmail(ownerFieldsDto.getEmail());
518	        if (!normalizeEmail(currentOwner)) {
519	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
520	        }
521	        this.clinicService.saveOwner(currentOwner);
522	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
523	    }
524	
525	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
526	    @Transactional
527	    @Override
528	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
529	        Owner owner = this.clinicService.findOwnerById(ownerId);
530	        if (owner == null) {
531	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
532	        }
533	        this.clinicService.deleteOwner(owner);
534	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
535	    }
