537	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
538	    @Override
539	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
540	        Owner owner = this.clinicService.findOwnerById(ownerId);
541	        if (owner == null) {
542	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
543	        }
544	        HttpHeaders headers = new HttpHeaders();
545	        Pet pet = petMapper.toPet(petFieldsDto);
546	        owner.setId(ownerId);
547	        pet.setOwner(owner);
548	        pet.getType().setName(null);
549	        this.clinicService.savePet(pet);
550	        PetDto petDto = petMapper.toPetDto(pet);
551	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
552	            .buildAndExpand(pet.getId()).toUri());
553	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
554	    }
