556	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
557	    @Override
558	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
559	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
560	        if (currentOwner != null) {
561	            Pet currentPet = this.clinicService.findPetById(petId);
562	            if (currentPet != null) {
563	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
564	                currentPet.setName(petFieldsDto.getName());
565	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
566	                this.clinicService.savePet(currentPet);
567	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
568	            }
569	        }
570	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
571	    }
