574	    @Override
575	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
576	        HttpHeaders headers = new HttpHeaders();
577	        Visit visit = visitMapper.toVisit(visitFieldsDto);
578	        Pet pet = new Pet();
579	        pet.setId(petId);
580	        visit.setPet(pet);
581	        this.clinicService.saveVisit(visit);
582	        VisitDto visitDto = visitMapper.toVisitDto(visit);
583	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
584	            .buildAndExpand(visit.getId()).toUri());
585	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
