588	
589	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
590	    @Override
591	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
592	        Owner owner = this.clinicService.findOwnerById(ownerId);
593	        if (owner != null) {
594	            Pet pet = owner.getPet(petId);
595	            if (pet != null) {
596	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
597	            }
