15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
23	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
24	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
25	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
26	    @Mapping(target = "locality", expression = "java(locality(owner))")
27	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
28	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
29	    OwnerDto toOwnerDto(Owner owner);
30	
31	    /**
32	     * Derives the owner's age band from {@code birthDate} measured against {@code registrationDate}:
33	     * {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and {@code SENIOR} at 65 or older.
34	     * Returns {@code null} when no birthDate is recorded. When the registrationDate is absent (e.g.
35	     * legacy records) the current date is used as the reference point.
36	     */
37	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
38	        java.time.LocalDate birthDate = owner.getBirthDate();
39	        if (birthDate == null) {
40	            return null;
41	        }
42	        java.time.LocalDate reference = owner.getRegistrationDate() != null
43	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
44	        int age = java.time.Period.between(birthDate, reference).getYears();
45	        if (age < 18) {
46	            return OwnerDto.AgeBandEnum.MINOR;
47	        }
48	        if (age < 65) {
49	            return OwnerDto.AgeBandEnum.ADULT;
50	        }
51	        return OwnerDto.AgeBandEnum.SENIOR;
52	    }
53	
54	    /**
55	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is
56	     * present, otherwise {@code PHONE}.
57	     */
58	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
59	        String email = owner.getEmail();
60	        if (email != null && !email.isEmpty()) {
61	            return OwnerDto.ContactPreferenceEnum.EMAIL;
62	        }
63	        return OwnerDto.ContactPreferenceEnum.PHONE;
64	    }
65	
